    int ty = threadIdx.y;
    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tile of A into shared memory
        int a_col = tile * TILE_SIZE + tx;
        if (row < N && a_col < N) {
            shared_A[ty][tx] = A[row * N + a_col];
        } else {
            shared_A[ty][tx] = 0.0f;
