        // Load tile of B into shared memory
        int b_row = tile * TILE_SIZE + ty;
        if (b_row < N && col < N) {
            shared_B[ty][tx] = B[b_row * N + col];
        } else {
            shared_B[ty][tx] = 0.0f;
