#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define REG_TILE 2

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float shared_A[TILE_SIZE][TILE_SIZE];
    __shared__ float shared_B[TILE_SIZE][TILE_SIZE];

    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row_base = blockIdx.y * TILE_SIZE + ty;
    int col_base = blockIdx.x * TILE_SIZE + tx;

    // Register blocking: each thread computes REG_TILE x REG_TILE elements
    float sum[REG_TILE][REG_TILE] = {0.0f};

    // Loop over tiles
    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; ++tile) {
        // Load tile of A into shared memory
        int a_col = tile * TILE_SIZE + tx;
        if (row_base < N && a_col < N) {
            shared_A[ty][tx] = A[row_base * N + a_col];
        } else {
            shared_A[ty][tx] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = tile * TILE_SIZE + ty;
        if (b_row < N && col_base < N) {
            shared_B[ty][tx] = B[b_row * N + col_base];
        } else {
            shared_B[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot products for register tile
        for (int k = 0; k < TILE_SIZE; ++k) {
            for (int i = 0; i < REG_TILE; ++i) {
                for (int j = 0; j < REG_TILE; ++j) {
                    int row_offset = i * (TILE_SIZE / REG_TILE);
                    int col_offset = j * (TILE_SIZE / REG_TILE);
                    if (ty + row_offset < TILE_SIZE && tx + col_offset < TILE_SIZE) {
                        sum[i][j] += shared_A[ty + row_offset][k] * shared_B[k][tx + col_offset];
